function grid$sysgroupinfo(f){
  this.constructor(f);
}
grid$sysgroupinfo.prototype = new DirEvent();
grid$sysgroupinfo.prototype.afterInit = function(){
	var p = this._dir;
}
grid$sysgroupinfo.prototype.beforeButtonGridClick = function(id){
  if (id == 'permission') {
    var p = this._dir;
    var m = new Memvars();
    p.grequest(0, 'permission', 'GetRow', 'group_id', funResult);
    return false;
  }
  return true
}
function funResult(p, d){
  d = new DataRow(d);
  if(d.val('result') == '')
    $.createDir(false, { controller: 'permissionGroup', backdropclick: false, folder: "Filter", dirViewType: "Dialog", parent: p });   
  else
    $.alert($.msg.get(d.val('result')));
}
